#!/usr/bin/env node
/**
 * check-site-mode.mjs — T-15 (Step 3 §9, AC-08): with SITE_MODE=public the
 * build FAILS while any DISPLAYED source has public_display_ok other than
 * 'yes'. SITE_MODE defaults to 'private' — the gate stays on and this check
 * is a no-op (it logs the mode and exits 0).
 *
 * Sources of truth (both generated by scripts/generate-indicators-registry.ts
 * and cross-checked by tests): data/indicator-audit.json (per-indicator
 * licence verdicts) and data/site-mode-overrides.json (the hidden set —
 * every verdict other than 'yes', fail-closed 'unknown' included, plus
 * every EODHD/Yahoo-backed world board that carries no owner directive;
 * the LR-02 hard line: Yahoo data must never appear when SITE_MODE=public
 * unless the owner directs it on their own site, as they did for the
 * markets board, 2026-10-18b).
 *
 * The 2026-10-19 owner decree ("make it public") turned this check into a
 * REAL gate with a pass path: public mode passes only when the overrides
 * file hides exactly the non-'yes' audit set — and keeps BOTH world boards
 * public on their owner directives (markets 2026-10-18b, fx 2026-10-21c
 * — the currencies-section restoration; both key-pinned below).
 *
 * Wired into apps/web's build: "build": "node ../../scripts/check-site-mode.mjs && vite build".
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(HERE, '..');

const mode = (process.env.SITE_MODE ?? 'private').toLowerCase();
if (mode !== 'public') {
  console.log(`[site-mode] SITE_MODE=${mode} — the private gate stays on; T-15 public-display check not applicable.`);
  process.exit(0);
}

console.log('[site-mode] SITE_MODE=public — verifying the hidden set covers every non-public-display-ok source (T-15)…');

const audit = JSON.parse(readFileSync(resolve(REPO, 'data', 'indicator-audit.json'), 'utf8'));
const failures = [];
const mustHide = audit.indicators.filter((e) => e.publicDisplayOk !== 'yes').map((e) => e.id);

const overridesPath = resolve(REPO, 'data', 'site-mode-overrides.json');
if (!existsSync(overridesPath)) {
  failures.push('data/site-mode-overrides.json does not exist — the hidden set is undeclared (fail closed)');
} else {
  let overrides;
  try {
    overrides = JSON.parse(readFileSync(overridesPath, 'utf8'));
  } catch (err) {
    failures.push(`data/site-mode-overrides.json is not valid JSON: ${err.message}`);
    overrides = undefined;
  }
  if (overrides !== undefined) {
    const hidden = new Set(overrides.hiddenIndicatorIds ?? []);
    const hiddenBoards = new Set(overrides.hiddenBoards ?? []);
    const boardDirectives = overrides.ownerBoardDirectives ?? {};
    for (const id of mustHide) {
      if (!hidden.has(id)) {
        const entry = audit.indicators.find((e) => e.id === id);
        failures.push(`${id}: public_display_ok='${entry.publicDisplayOk}' (${entry.licenceName}) is NOT hidden by site-mode-overrides.json — it would be displayed publicly`);
      }
    }
    for (const id of hidden) {
      if (!mustHide.includes(id)) {
        failures.push(`${id} is hidden by site-mode-overrides.json but its audit verdict is 'yes' — the overrides file is stale (re-run the registry generator)`);
      }
    }
    // 2026-10-21c owner directive: the world FX board (ECB reference rates
    // via Frankfurter — the same rates the public converter displays; terms
    // verified 2026-10-21) is PUBLIC again. It must never be re-hidden by a
    // generator change without the owner saying so — and its directive note
    // must ride in the file (the honest trail), exactly like the markets
    // board's.
    if (hiddenBoards.has('fx')) {
      failures.push('the world fx board is hidden by site-mode-overrides.json — the 2026-10-21c owner directive (currencies-section restoration) keeps it PUBLIC; only the owner can re-hide it');
    }
    if (typeof boardDirectives.fx !== 'string' || boardDirectives.fx.length === 0) {
      failures.push('the fx board is public but ownerBoardDirectives.fx is missing — the owner-directive evidence note must ride in the generated file');
    }
    // 2026-10-18b owner directive: the world MARKETS board is public again
    // (the owner's own EODHD key backs it). It must never be re-hidden by a
    // generator change without the owner saying so — and its directive
    // note must ride in the file (the honest trail).
    if (hiddenBoards.has('markets')) {
      failures.push('the world markets board is hidden by site-mode-overrides.json — the 2026-10-18b owner directive keeps it PUBLIC; only the owner can re-hide it');
    }
    if (typeof boardDirectives.markets !== 'string' || boardDirectives.markets.length === 0) {
      failures.push('the markets board is public but ownerBoardDirectives.markets is missing — the owner-directive evidence note must ride in the generated file');
    }
  }
}

if (failures.length > 0) {
  console.error(`[site-mode] T-15 FAILED — ${failures.length} public-display problem(s):`);
  for (const f of failures) console.error(`  ✗ ${f}`);
  console.error('[site-mode] The public build is refused. Resolve the licences (or keep SITE_MODE=private).');
  process.exit(1);
}

console.log(
  `[site-mode] T-15 passed — ${mustHide.length} indicator(s) hidden by site-mode-overrides.json; the markets board rides the 2026-10-18b owner directive and the fx board the 2026-10-21c restoration directive; every displayed source is public-display-ok or owner-directed.`,
);
process.exit(0);
